const cache = new Map<string, { data: unknown; expiry: number }>();

async function fetchFromSource(key: string): Promise<unknown> {
  await new Promise(r => setTimeout(r, 100));
  return { key, value: Math.random() };
}

// BUG: concurrent calls for the same key each
// trigger a separate source fetch, causing
// inconsistency and wasted resources.
export async function fetchWithCache(key: string, ttlMs = 5000): Promise<unknown> {
  const cached = cache.get(key);
  if (cached && cached.expiry > Date.now()) {
    return cached.data;
  }
  const data = await fetchFromSource(key);
  cache.set(key, { data, expiry: Date.now() + ttlMs });
  return data;
}

export function clearCache(): void {
  cache.clear();
}
